//! US 12,417,870 ("driving movement of a target object by a gravitational field generated by a
//! varying electromagnetic field", Zhang, Xiao & Li, 2025) rebuilt from its embodiment and
//! computed: every classical force on the ball, the gas in its "near vacuum", what the theory
//! behind it predicts in its own terms, and what general relativity predicts. Then the same
//! authors' weighing rig, and the test that would separate the explanations.
//!
//! ```text
//! cargo run -p physica --example gravity_patent
//! ```

use core::f64::consts::PI;

use gravitics::electrodes::{Ring, charges, field, stack};
use gravitics::electrogravity::{
    COPPER_ELECTRONS, drift_velocity, field_charge, field_energy_gravity, rotation_torque, sphere_force, torsion_constant,
};
use magnetics::magnets::solenoid_bz;
use metrology::G0;
use plasmoid::discharge::{AIR, AIR_DIAMETER, mean_free_path, paschen, peek_onset};

fn main() {
    // The embodiment: a 10 cm vacuum tank between two 12-turn coils of silicone wire (10 mm
    // across, 1.5 mm copper inside), wound 8 cm across and 12 cm tall. The upper coil is fed 50 kV
    // at about 10 µA; the lower coil is grounded. A 0.35 g polyethylene ball hangs in the middle.
    let mut rings = stack(0.035, 0.065, 0.01, 12);
    rings.extend(stack(0.035, -0.065, -0.01, 12));
    let volts: Vec<f64> = (0..24).map(|i| if i < 12 { 50e3 } else { 0.0 }).collect();
    let q = charges(&rings, 0.75e-3, &volts);
    let e2 = |z: f64| {
        let [a, b] = field(&rings, &q, 0.0, z);
        a * a + b * b
    };
    let e = e2(0.0).sqrt();
    let grad = (e2(1e-4) - e2(-1e-4)) / 2e-4;
    let energy = 0.5 * q[..12].iter().sum::<f64>() * 50e3;
    println!("US 12,417,870 at 50 kV: {e:.3e} V/m at the ball, ∇E² = {grad:.2e} V²/m³, {:.1} mJ stored", energy * 1e3);

    let (mass, radius, eps) = (0.35e-3, 4.447e-3, 2.3);
    let weight = mass * G0;
    let pull = sphere_force(radius, eps, grad);
    let charge = field_charge(radius, eps, e);
    let torque = rotation_torque(radius, eps, e);
    let kappa = torsion_constant(0.4 * mass * radius * radius, 30.0);
    println!("forces on the ball, against its weight of {:.2} mN:", weight * 1e3);
    println!("  pulled toward the live coil:            {:.2e} of its weight", pull / weight);
    println!("  if ions charge it ({:.2} nC), pulled:     {:.3} of its weight", charge * 1e9, charge * e / weight);
    println!("  polarisation torque, at most {torque:.1e} N m: {:.0} turns of a thread with a 30 s twist", torque / kappa / (2.0 * PI));
    assert!((pull / weight - 5.50e-4).abs() < 1e-5 && (charge * e / weight - 0.0643).abs() < 1e-3);

    // The patent says only "near vacuum". Whether the tank holds ions decides the charge above.
    println!("the gas in the tank (10 cm):");
    for p in [100.0, 10.0, 1.0, 0.1, 0.01] {
        let breakdown = paschen(AIR, 0.01, p * 0.1).map_or("cannot break down".to_string(), |v| format!("breaks down at {v:.0} V"));
        println!("  {p:>6} Pa: mean free path {:.1e} m, {breakdown}", mean_free_path(p, 293.15, AIR_DIAMETER));
    }
    println!("  the open copper ends in air go into corona above {:.1} MV/m", peek_onset(0.75e-3, 1.0) / 1e6);

    // The magnetic field the "varying electromagnetic field" can have: the coils are open, so
    // only the charging current flows.
    let b = solenoid_bz(0.12, 0.035, 0.12, 100.0, 10e-6);
    println!("B at the ball from 10 µA: {b:.1e} T, {:.1e} of Earth's field", b / 50e-6);
    assert!(b < 1e-10);

    // The theory's own field is the charges' acceleration: a body gains at most their drift velocity.
    let v = drift_velocity(10e-6, COPPER_ELECTRONS, PI * 0.75e-3 * 0.75e-3);
    println!("the theory in its own terms: carriers drift at {v:.1e} m/s; at the 30 kHz ripple the ball moves {:.0e} m", v / (2.0 * PI * 3e4));
    println!("general relativity: the field energy pulls {:.1e} m/s² at 6 cm", field_energy_gravity(energy, 0.06));

    // The weighing rig (Zhang & Xu): a nylon ring (radii 20 and 50 mm, 50 mm tall) around a wire
    // with a 50 mm gap at 55 kV, reported 0.83–1.20 g lighter with the top live and 0.76–1.08 g
    // heavier the other way round. The wires are modelled as stacks of rings of their own radius.
    println!("the weighing rig, the polarisation pull on the nylon ring (reported: −1.0 g, +0.9 g):");
    for (name, top, bottom) in [("top live", 55e3, 0.0), ("bottom live", 0.0, 55e3), ("±27.5 kV", 27.5e3, -27.5e3)] {
        let lift = ring_pull(top, bottom) / G0 * 1e3; // grams lifted per unit of ε_r − 1
        println!("  {name:<12} weighs {:+.2} to {:+.2} g", 0.0 - lift * 2.6, 0.0 - lift * 0.722);
        if top == -bottom {
            assert!(lift.abs() < 1e-6); // the live-end test: symmetric drive, no pull
        } else {
            assert!(lift.abs() > 0.03 && lift.abs() < 0.2 && lift.signum() == if top > 0.0 { 1.0 } else { -1.0 });
        }
    }
    println!("  a gravitational field from the charges would not care which side is grounded");
}

/// The upward polarisation force (N) on the nylon ring, `½ε₀(ε_r − 1)∫(E²_top − E²_bottom)dA`, per
/// unit of `ε_r − 1`: multiply by 2.6 for the dilute limit and by 0.72 (`1 − 1/ε_r`) for a field
/// normal to the ring's faces, the two ends of the range for nylon (ε_r = 3.6).
fn ring_pull(top: f64, bottom: f64) -> f64 {
    let (a, n) = (0.75e-3, 200);
    let mut rings: Vec<Ring> = stack(a, 0.025 + a, 2.0 * a, n);
    rings.extend(stack(a, -0.025 - a, -2.0 * a, n));
    let volts: Vec<f64> = (0..2 * n).map(|i| if i < n { top } else { bottom }).collect();
    let q = charges(&rings, a, &volts);
    let e2 = |rho: f64, z: f64| {
        let [x, y] = field(&rings, &q, rho, z);
        x * x + y * y
    };
    let steps = 60;
    let dr = 0.03 / steps as f64;
    let integral: f64 = (0..=steps)
        .map(|i| {
            let rho = 0.02 + dr * i as f64;
            let w = if i == 0 || i == steps { 0.5 } else { 1.0 };
            w * (e2(rho, 0.025) - e2(rho, -0.025)) * 2.0 * PI * rho * dr
        })
        .sum();
    0.5 * metrology::EPS_0 * integral
}

#[test]
fn the_patent_rig_has_classical_forces_to_spare() {
    main();
}
